// The "start a campaign" form's checks, as plain functions. They are a courtesy to the visitor:
// the create-campaign function is the real enforcement point and repeats every one of them.

export const MAX_IMAGE_BYTES = 1 * 1024 * 1024; // keep in sync with the function (MAX_IMAGE_BYTES)
export const ALLOWED_IMAGE_TYPES: readonly string[] = ['image/jpeg', 'image/png', 'image/webp'];
export const MAX_OTHER_LINKS = 10;

/** The same slug rule the function applies to an empty slug field: derived from the campaign name. */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/** Error message, or null when the file is fine. */
export function validateImage(file: { type: string; size: number } | null | undefined): string | null {
  if (!file) return 'An image is required.';
  if (!ALLOWED_IMAGE_TYPES.includes(file.type)) return 'Image must be JPEG, PNG, or WebP.';
  if (file.size > MAX_IMAGE_BYTES) return 'Image must be under 1MB.';
  return null;
}

/** The end date is optional; if given it must be in the future. `value` is a datetime-local string. */
export function validateTargetDate(value: string, now: number = Date.now()): string | null {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return 'Invalid end date.';
  if (d.getTime() <= now) return 'Campaign end date must be in the future.';
  return null;
}

/** The earliest end date the picker offers: at least an hour out (a nicety; the function enforces it). */
export function minTargetDate(now: number = Date.now()): string {
  return new Date(now + 60 * 60 * 1000).toISOString().slice(0, 16);
}

/** The webhook URL is optional; if given it must be a valid https URL. */
export function validateWebhookUrl(raw: string): string | null {
  const v = raw.trim();
  if (!v) return null;
  try {
    if (new URL(v).protocol !== 'https:') return 'Webhook URL should use https:// for security.';
  } catch {
    return 'Invalid webhook URL.';
  }
  return null;
}

/** Only complete rows (label and URL), trimmed. */
export function collectOtherLinks(rows: Array<{ label: string; url: string }>): Array<{ label: string; url: string }> {
  const links: Array<{ label: string; url: string }> = [];
  for (const row of rows) {
    const label = row.label.trim();
    const url = row.url.trim();
    if (label && url) links.push({ label, url });
  }
  return links;
}
