import { BaseElement } from '../common/base-element';
import { config } from '../config';
import { resolveSupabaseUrl } from '../common/runtime-config';
import { escapeHtml } from '../campaigns/safe';
import {
  ALLOWED_IMAGE_TYPES,
  collectOtherLinks,
  MAX_OTHER_LINKS,
  minTargetDate,
  slugify,
  validateImage,
  validateTargetDate,
  validateWebhookUrl,
} from './validation';

// Production's "start a campaign" form CSS (squarespace-campaign-form-widget.html), the same rules
// with the same ids; `#campaign-form-root` is the form's container inside this element.
const STYLES = `
:host { display: block; }
#campaign-form-root { max-width: 560px; margin: 0 auto; }
.cf-field { margin-bottom: 1.25em; display: flex; flex-direction: column; gap: 0.35em; }
.cf-field label, .cf-field legend { font-weight: 600; }
.cf-field input, .cf-field textarea { padding: 0.6em; border: 1px solid #ccc; border-radius: 4px; font: inherit; }
.cf-slug-row { display: flex; align-items: center; gap: 0.4em; }
.cf-slug-prefix { color: #666; white-space: nowrap; font-size: 0.9em; }
.cf-optional { font-weight: 400; color: #888; font-size: 0.85em; }
fieldset.cf-field { border: 1px solid #ddd; border-radius: 6px; padding: 1em; }
fieldset.cf-field input { margin-bottom: 0.5em; }
.cf-honeypot { position: absolute; left: -9999px; top: -9999px; }
.cf-error { color: #b00020; font-size: 0.9em; }
#cf-other-links .cf-other-link-row { display: flex; gap: 0.5em; margin-bottom: 0.5em; }
#cf-submit { padding: 0.75em 1.5em; font-weight: 600; cursor: pointer; font-family: inherit; }
#cf-submit:disabled { opacity: 0.6; cursor: not-allowed; }
/* Not in production (it overflowed a phone, making the page 512px wide at a 390px viewport): on a
   narrow screen the URL prefix gets its own line and the field takes the full width below it.
   Wider than 480px nothing changes. */
@media (max-width: 480px) {
  .cf-slug-row { flex-wrap: wrap; }
  .cf-slug-prefix { white-space: normal; overflow-wrap: anywhere; }
  .cf-slug-row input { flex: 1 1 100%; min-width: 0; }
}
`;

/** "realgoodai.org" for https://www.realgoodai.org: what production's form printed before the slug field. */
function siteHost(): string {
  try {
    return new URL(config.siteUrl).host.replace(/^www\./, '');
  } catch {
    return '';
  }
}

/**
 * <rg-campaign-form>: the "start a campaign" form. Posts multipart form data to the
 * `create-campaign` function and goes to the new campaign's page. It has the honeypot field and the
 * time-on-form stamp the function checks, a slug that is suggested from the campaign name, social
 * and other links, an optional end date and webhook URL, and the image checks (up to 1 MB; JPEG,
 * PNG or WebP). The function repeats every check: these are a courtesy to the visitor.
 */
export class RgCampaignForm extends BaseElement {
  private otherLinkCount = 0;

  constructor() {
    super(STYLES);
  }

  connectedCallback(): void {
    this.render();
  }

  private render(): void {
    this.otherLinkCount = 0;
    this.setHtml(`
    <div id="campaign-form-root">
      <form id="campaign-form" novalidate>
        <div class="cf-field">
          <label for="cf-name">Campaign name</label>
          <input id="cf-name" name="name" type="text" maxlength="100" required />
        </div>
        <div class="cf-field">
          <label for="cf-organizer-name">Your name (shown publicly on the page)</label>
          <input id="cf-organizer-name" name="organizer_name" type="text" maxlength="100" required />
        </div>
        <div class="cf-field">
          <label for="cf-slug">Campaign URL</label>
          <div class="cf-slug-row">
            <span class="cf-slug-prefix">${escapeHtml(siteHost())}/fundraising-campaigns/p/</span>
            <input id="cf-slug" name="slug" type="text" maxlength="60" pattern="[a-z0-9-]+" />
          </div>
          <small>Leave blank to auto-generate from the campaign name.</small>
        </div>
        <div class="cf-field">
          <label for="cf-description">Description</label>
          <textarea id="cf-description" name="description" rows="5" maxlength="2000" required></textarea>
        </div>
        <div class="cf-field">
          <label for="cf-goal">Goal (USD)</label>
          <input id="cf-goal" name="goal_dollars" type="number" min="1" step="1" required />
        </div>
        <div class="cf-field">
          <label for="cf-target-date">Campaign end date <span class="cf-optional">(optional)</span></label>
          <input id="cf-target-date" name="target_date" type="datetime-local" />
          <small>Leave blank for an ongoing campaign with no end date. Shown to visitors as "X days left".</small>
          <p id="cf-target-date-error" class="cf-error" hidden></p>
        </div>
        <div class="cf-field">
          <label for="cf-image">Campaign image</label>
          <input id="cf-image" name="image" type="file" accept="${ALLOWED_IMAGE_TYPES.join(',')}" required />
          <small>JPEG, PNG or WebP. 1MB max. 16:9 aspect ratio recommended.</small>
          <p id="cf-image-error" class="cf-error" hidden></p>
        </div>
        <fieldset class="cf-field">
          <legend>Social links (optional)</legend>
          <input name="twitch_url" type="url" placeholder="Twitch URL" />
          <input name="youtube_url" type="url" placeholder="YouTube URL" />
          <input name="tiktok_url" type="url" placeholder="TikTok URL" />
          <input name="instagram_url" type="url" placeholder="Instagram URL" />
          <input name="discord_url" type="url" placeholder="Discord URL" />
        </fieldset>
        <div class="cf-field">
          <div id="cf-other-links"></div>
          <button type="button" id="cf-add-link">+ Add another link</button>
        </div>
        <div class="cf-field">
          <label for="cf-webhook-url">Donation webhook URL <span class="cf-optional">(optional)</span></label>
          <input id="cf-webhook-url" name="webhook_url" type="url" maxlength="2048" placeholder="https://example.com/hooks/abc123..." />
          <small>Get a notification (e.g. in-game via a Minecraft mod) whenever your campaign receives a donation. Use HTTPS, and include a long random token in the URL (rather than a guessable path) since anyone who has this URL can trigger it — treat it like a password.</small>
          <p id="cf-webhook-url-error" class="cf-error" hidden></p>
        </div>
        <div class="cf-field">
          <label for="cf-email">Your email (not shown publicly, used only if we need to reach you)</label>
          <input id="cf-email" name="email" type="email" />
        </div>
        <!-- Honeypot: real visitors never see this field. Off-screen rather than display:none, since
             some bots skip display:none / visibility:hidden fields. -->
        <div class="cf-honeypot" aria-hidden="true">
          <label for="cf-website">Website</label>
          <input id="cf-website" name="website" type="text" tabindex="-1" autocomplete="off" />
        </div>
        <input type="hidden" name="form_rendered_at" id="cf-rendered-at" />
        <p id="cf-form-error" class="cf-error" hidden></p>
        <button type="submit" id="cf-submit">Create campaign</button>
      </form>
    </div>`);
    this.wire();
  }

  private wire(): void {
    const q = <T extends HTMLElement>(sel: string) => this.$<T>(sel)!;
    const form = q<HTMLFormElement>('#campaign-form');
    const nameInput = q<HTMLInputElement>('#cf-name');
    const slugInput = q<HTMLInputElement>('#cf-slug');
    const imageInput = q<HTMLInputElement>('#cf-image');
    const imageError = q('#cf-image-error');
    const targetDateInput = q<HTMLInputElement>('#cf-target-date');
    const targetDateError = q('#cf-target-date-error');
    const webhookInput = q<HTMLInputElement>('#cf-webhook-url');
    const webhookError = q('#cf-webhook-url-error');
    const formError = q('#cf-form-error');
    const submitBtn = q<HTMLButtonElement>('#cf-submit');
    const otherLinks = q('#cf-other-links');

    const show = (el: HTMLElement, message: string | null) => {
      el.hidden = !message;
      el.textContent = message ?? '';
    };

    // The time-on-form stamp the function uses to spot bots that submit instantly.
    q<HTMLInputElement>('#cf-rendered-at').value = String(Date.now());
    targetDateInput.min = minTargetDate();

    // Suggest the URL from the name, as a placeholder; typing in the field overrides it.
    nameInput.addEventListener('input', () => {
      slugInput.placeholder = slugify(nameInput.value);
    });

    q('#cf-add-link').addEventListener('click', () => {
      if (this.otherLinkCount >= MAX_OTHER_LINKS) return;
      this.otherLinkCount++;
      const row = document.createElement('div');
      row.className = 'cf-other-link-row';
      row.innerHTML =
        '<input type="text" class="cf-other-link-label" placeholder="Label (e.g. Website)" maxlength="40" />' +
        '<input type="url" class="cf-other-link-url" placeholder="https://..." />' +
        '<button type="button" class="cf-remove-link">Remove</button>';
      row.querySelector('.cf-remove-link')!.addEventListener('click', () => row.remove());
      otherLinks.appendChild(row);
    });

    imageInput.addEventListener('change', () => show(imageError, validateImage(imageInput.files?.[0])));

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      show(formError, null);

      const imgErr = validateImage(imageInput.files?.[0]);
      show(imageError, imgErr);
      if (imgErr) return;

      const dateErr = validateTargetDate(targetDateInput.value);
      show(targetDateError, dateErr);
      if (dateErr) return;

      const hookErr = validateWebhookUrl(webhookInput.value);
      show(webhookError, hookErr);
      if (hookErr) return;

      const formData = new FormData(form);
      const rows = [...otherLinks.querySelectorAll('.cf-other-link-row')].map((row) => ({
        label: row.querySelector<HTMLInputElement>('.cf-other-link-label')!.value,
        url: row.querySelector<HTMLInputElement>('.cf-other-link-url')!.value,
      }));
      formData.set('other_links', JSON.stringify(collectOtherLinks(rows)));
      if (targetDateInput.value) formData.set('target_date', new Date(targetDateInput.value).toISOString());
      else formData.delete('target_date');

      submitBtn.disabled = true;
      submitBtn.textContent = 'Creating...';

      fetch(`${resolveSupabaseUrl()}/functions/v1/create-campaign`, { method: 'POST', body: formData })
        .then(async (res) => {
          const body = (await res.json()) as { error?: string; url?: string };
          if (!res.ok) throw new Error(body.error || 'Something went wrong');
          return body;
        })
        .then((body) => {
          if (!body.url) throw new Error('Something went wrong');
          window.location.href = body.url;
        })
        .catch((err: unknown) => {
          show(formError, (err instanceof Error && err.message) || 'Something went wrong. Please try again.');
          submitBtn.disabled = false;
          submitBtn.textContent = 'Create campaign';
        });
    });
  }
}

if (!customElements.get('rg-campaign-form')) customElements.define('rg-campaign-form', RgCampaignForm);
